import type { ReactNode } from 'react';

import {
  StyledPhiOvertimeCardHeader,
  StyledPhiOvertimeSubtitle,
  StyledPhiSectionInnerCard,
} from '../../Overview.styles';
import { resolveBeerEvolutionTestId } from './beerEvolutionBreakdownSection.utils';

interface BeerEvolutionEmbeddedSectionProps {
  title: string;
  dataTestId?: string;
  children: ReactNode;
}

export const BeerEvolutionEmbeddedSection = ({
  title,
  dataTestId,
  children,
}: BeerEvolutionEmbeddedSectionProps) => (
  <StyledPhiSectionInnerCard
    data-testid={resolveBeerEvolutionTestId(
      dataTestId,
      'inner-card',
      'beer-evolution-breakdown-inner-card',
    )}
  >
    <StyledPhiOvertimeCardHeader
      data-testid={resolveBeerEvolutionTestId(
        dataTestId,
        'card-header',
        'beer-evolution-card-header',
      )}
    >
      <StyledPhiOvertimeSubtitle
        data-testid={resolveBeerEvolutionTestId(
          dataTestId,
          'subtitle',
          'beer-evolution-subtitle',
        )}
      >
        {title}
      </StyledPhiOvertimeSubtitle>
    </StyledPhiOvertimeCardHeader>
    {children}
  </StyledPhiSectionInnerCard>
);
